import csv
import io
import re


def parse_csv(raw_csv: str):
    class CommentFilteringLines:
        def __init__(self, text):
            self.lines = iter(io.StringIO(text, newline=""))
            self.record_start = True

        def __iter__(self):
            return self

        def __next__(self):
            while True:
                line = next(self.lines)
                if self.record_start and line.lstrip("\ufeff \t").startswith("#"):
                    continue
                self.record_start = False
                return line

    lines = CommentFilteringLines(raw_csv)
    reader = csv.reader(lines, delimiter=",", quotechar='"')
    records = []

    while True:
        lines.record_start = True
        try:
            row = next(reader)
        except StopIteration:
            break
        if row:
            records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    records[0][0] = records[0][0].lstrip("\ufeff")
    number = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )
    first = records[0]
    nonempty = [value.strip() for value in first if value.strip()]
    numeric_count = sum(bool(number.fullmatch(value)) for value in nonempty)
    first_is_data = bool(nonempty) and numeric_count * 2 >= len(nonempty)

    if first_is_data:
        rows = records
        columns = []
    else:
        columns = first[:]
        rows = records[1:]

    width = max([len(columns)] + [len(row) for row in rows])
    columns.extend("column_{}".format(i + 1) for i in range(len(columns), width))
    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
